216	function InspectModal({ taskId, readonly, onClose, onSubmitted }) {
217	  const toast = useToast();
218	  const [task, setTask] = useState(null);
219	  const [items, setItems] = useState([]);
220	  const [inspector, setInspector] = useState("");
221	  const [remark, setRemark] = useState("");
222	  // itemId -> { value, normal, phenomenon, severity }
223	  const [form, setForm] = useState({});
224	  const [busy, setBusy] = useState(false);
225	
226	  useEffect(() => {
227	    api.task(taskId).then(async (detail) => {
228	      setTask(detail);
229	      setInspector(detail.inspector || "");
230	      setRemark(detail.remark || "");
231	      const itemsData = await api.itemsByCategory(detail.equipment_category);
232	      setItems(itemsData);
233	      const initial = {};
234	      itemsData.forEach((it) => {
235	        const existing = detail.readings?.find((r) => r.item === it.id);
236	        initial[it.id] = existing
237	          ? {
238	              value: existing.value ?? "",
239	              normal: existing.normal,
240	              phenomenon: "",
241	              severity: "low",
242	            }
243	          : { value: "", normal: true, phenomenon: "", severity: "low" };
244	      });
245	      setForm(initial);
246	    });
247	  }, [taskId]);
248	
249	  const update = (id, patch) =>
250	    setForm((f) => ({ ...f, [id]: { ...f[id], ...patch } }));
251	
252	  const evaluateParam = (item, value) => {
253	    if (value === "" || value === null) return true;
254	    const v = Number(value);
255	    if (Number.isNaN(v)) return false;
256	    const lo = item.lower_limit, hi = item.upper_limit;
257	    return (lo === null || v >= lo) && (hi === null || v <= hi);
258	  };
259	
260	  const abnormalRows = useMemo(
261	    () =>
262	      items.filter((it) => {
263	        const row = form[it.id];
264	        if (!row) return false;
265	        return it.kind === "param"
266	          ? !evaluateParam(it, row.value)
267	          : row.normal === false;
268	      }),
269	    [items, form]
270	  );
271	
272	  const submit = async () => {
273	    if (!inspector.trim()) return toast("请填写点检人", "err");
274	    // 参数项必须填写
275	    const missing = items.filter(
276	      (it) => it.kind === "param" && form[it.id]?.value === ""
277	    );
278	    if (missing.length)
279	      return toast(`请填写参数：${missing.map((m) => m.name).join("、")}`, "err");
280	
281	    const readings = items.map((it) => {
282	      const row = form[it.id];
283	      const normal =
284	        it.kind === "param" ? evaluateParam(it, row.value) : row.normal;
285	      return {
286	        item: it.id,
287	        value: it.kind === "param" ? Number(row.value) : null,
288	        normal,
289	        phenomenon: normal ? "" : row.phenomenon,
290	        severity: normal ? "low" : row.severity,
291	      };
292	    });
293	    setBusy(true);
294	    try {
295	      await api.startTask(taskId, { inspector });
296	      const res = await api.submitTask(taskId, {
297	        inspector,
298	        remark,
299	        readings,
300	      });
301	      const n = res.abnormal_reports.length;
302	      toast(n ? `已提交，自动生成 ${n} 张异常报告` : "点检完成，全部正常");
303	      onSubmitted();
304	    } catch (e) {
305	      toast(e.message, "err");
306	    } finally {
307	      setBusy(false);
308	    }
309	  };
310	
311	  if (!task)
312	    return (
313	      <Modal title="加载中" onClose={onClose}>
314	        <div className="empty">加载任务详情…</div>
315	      </Modal>
316	    );
317	
318	  return (
319	    <Modal
320	      wide
321	      title={`点检 · ${task.task_no} · ${task.equipment_code} ${task.equipment_name}`}
322	      onClose={onClose}
323	      footer={
324	        <>
325	          <button className="secondary" onClick={onClose}>取消</button>
326	          {!readonly && (
327	            <button onClick={submit} disabled={busy}>
328	              {busy ? "提交中…" : `提交点检${abnormalRows.length ? `（${abnormalRows.length} 项异常）` : ""}`}
329	            </button>
330	          )}
331	        </>
332	      }
333	    >
334	      <div className="form-grid" style={{ marginBottom: 12 }}>
335	        <label className="field">
336	          点检人
337	          <input
338	            value={inspector}
339	            disabled={readonly}
340	            onChange={(e) => setInspector(e.target.value)}
341	            placeholder="请输入姓名"
342	          />
343	        </label>
344	        <label className="field">
345	          班次 / 日期
346	          <input value={`${task.shift_name} · ${task.task_date}`} disabled />
347	        </label>
348	      </div>
349	
350	      {items.map((it) => {
351	        const row = form[it.id] || {};
352	        const isAbnormal =
353	          it.kind === "param"
354	            ? !evaluateParam(it, row.value)
355	            : row.normal === false;
356	        return (
357	          <div key={it.id} className={isAbnormal ? "reading-row abnormal" : "reading-row"}>
358	            <div>
359	              <strong>{it.name}</strong>
360	              {it.kind === "param" && (
361	                <div className="rng">
362	                  标准范围：
363	                  {it.lower_limit ?? "−"} ~ {it.upper_limit ?? "−"} {it.unit}
364	                </div>
365	              )}
366	            </div>
367	            {it.kind === "param" ? (
368	              <input
369	                type="number"
370	                step="0.1"
371	                disabled={readonly}
372	                value={row.value ?? ""}
373	                placeholder={`数值${it.unit ? `（${it.unit}）` : ""}`}
374	                onChange={(e) => update(it.id, { value: e.target.value })}
375	              />
376	            ) : (
377	              <div className="radio-group">
378	                <button
379	                  type="button"
380	                  disabled={readonly}
381	                  className={row.normal === true ? "on-ok" : "off"}
382	                  onClick={() => update(it.id, { normal: true })}
383	                >
384	                  ✓ 正常
385	                </button>
386	                <button
387	                  type="button"
388	                  disabled={readonly}
389	                  className={row.normal === false ? "on-bad" : "off"}
390	                  onClick={() => update(it.id, { normal: false })}
391	                >
392	                  ✗ 异常
393	                </button>
394	              </div>
395	            )}
396	            <div>{isAbnormal ? <Badge value="abnormal" /> : <Badge value="done" />}</div>
397	            <div />
398	            {isAbnormal && !readonly && (
399	              <div className="full" style={{ gridColumn: "1 / -1", display: "flex", gap: 8 }}>
400	                <input
401	                  style={{ flex: 1 }}
402	                  placeholder="描述异常现象（留空则按超限值自动生成）"
403	                  value={row.phenomenon || ""}
404	                  onChange={(e) => update(it.id, { phenomenon: e.target.value })}
405	                />
406	                <select
407	                  value={row.severity || "low"}
408	                  onChange={(e) => update(it.id, { severity: e.target.value })}
409	                >
410	                  <option value="low">一般</option>
411	                  <option value="high">严重</option>
412	                  <option value="critical">紧急</option>
413	                </select>
414	              </div>
415	            )}
416	          </div>
417	        );
418	      })}
419	
420	      <label className="field" style={{ marginTop: 14 }}>
421	        备注
422	        <textarea
423	          value={remark}
424	          disabled={readonly}
425	          onChange={(e) => setRemark(e.target.value)}
426	          placeholder="整体备注（可选）"
427	        />
428	      </label>
429	      {readonly && (
430	        <p className="muted" style={{ marginTop: 10 }}>
431	          该任务已提交，记录只读。异常处理请前往「异常报告」页面。
432	        </p>
433	      )}
434	    </Modal>
435	  );
436	}
